bash: mkdir -p output && cat > output/scratch_dsl_script.json << 'EOF'
{
  "scripts": [
    {
      "hat": "event_whenflagclicked",
      "hatId": "hat_stage_init_1",
      "blocks": [
        {
          "opcode": "data_setvariableto",
          "inputs": { "VALUE": 0 },
          "fields": { "VARIABLE": "分数" }
        },
        {
          "opcode": "data_setvariableto",
          "inputs": { "VALUE": 5 },
          "fields": { "VARIABLE": "生命" }
        },
        {
          "opcode": "data_setvariableto",
          "inputs": { "VALUE": 30 },
          "fields": { "VARIABLE": "时间" }
        },
        {
          "opcode": "data_setvariableto",
          "inputs": { "VALUE": "ready" },
          "fields": { "VARIABLE": "状态" }
        },
        {
          "opcode": "looks_hide"
        },
        {
          "opcode": "control_wait",
          "inputs": { "DURATION": 2 }
        },
        {
          "opcode": "data_setvariableto",
          "inputs": { "VALUE": "playing" },
          "fields": { "VARIABLE": "状态" }
        },
        {
          "opcode": "event_broadcast",
          "inputs": { "BROADCAST_INPUT": "游戏开始" }
        },
        {
          "opcode": "control_forever",
          "inputs": {
            "SUBSTACK": [
              {
                "opcode": "control_if",
                "inputs": {
                  "CONDITION": {
                    "opcode": "operator_equals",
                    "inputs": {
                      "OPERAND1": { "opcode": "data_variable", "fields": { "VARIABLE": "状态" } },
                      "OPERAND2": "playing"
                    }
                  },
                  "SUBSTACK": [
                    {
                      "opcode": "control_repeat_until",
                      "inputs": {
                        "CONDITION": {
                          "opcode": "operator_lt",
                          "inputs": {
                            "OPERAND1": { "opcode": "data_variable", "fields": { "VARIABLE": "时间" } },
                            "OPERAND2": 0
                          }
                        },
                        "SUBSTACK": [
                          {
                            "opcode": "control_wait",
                            "inputs": { "DURATION": 1 }
                          },
                          {
                            "opcode": "data_changevariableby",
                            "inputs": { "VALUE": -1 },
                            "fields": { "VARIABLE": "时间" }
                          }
                        ]
                      }
                    },
                    {
                      "opcode": "data_setvariableto",
                      "inputs": { "VALUE": "gameover" },
                      "fields": { "VARIABLE": "状态" }
                    },
                    {
                      "opcode": "event_broadcast",
                      "inputs": { "BROADCAST_INPUT": "游戏结束" }
                    }
                  ]
                }
              }
            ]
          }
        }
      ]
    },
    {
      "hat": "event_whenbroadcastreceived",
      "hatId": "hat_stage_spawn_enemy_1",
      "hatFields": { "BROADCAST_OPTION": "生成敌人" },
      "blocks": [
        {
          "opcode": "control_forever",
          "inputs": {
            "SUBSTACK": [
              {
                "opcode": "control_if",
                "inputs": {
                  "CONDITION": {
                    "opcode": "operator_equals",
                    "inputs": {
                      "OPERAND1": { "opcode": "data_variable", "fields": { "VARIABLE": "状态" } },
                      "OPERAND2": "playing"
                    }
                  },
                  "SUBSTACK": [
                    {
                      "opcode": "control_if",
                      "inputs": {
                        "CONDITION": {
                          "opcode": "operator_and",
                          "inputs": {
                            "OPERAND1": {
                              "opcode": "operator_gt",
                              "inputs": {
                                "OPERAND1": { "opcode": "data_variable", "fields": { "VARIABLE": "分数" } },
                                "OPERAND2": 20
                              }
                            },
                            "OPERAND2": {
                              "opcode": "operator_gt",
                              "inputs": {
                                "OPERAND1": { "opcode": "data_variable", "fields": { "VARIABLE": "时间" } },
                                "OPERAND2": 5
                              }
                            }
                          }
                        },
                        "SUBSTACK": [
                          {
                            "opcode": "control_wait",
                            "inputs": { "DURATION": 0.3 }
                          }
                        ]
                      }
                    },
                    {
                      "opcode": "control_if",
                      "inputs": {
                        "CONDITION": {
                          "opcode": "operator_gt",
                          "inputs": {
                            "OPERAND1": { "opcode": "data_variable", "fields": { "VARIABLE": "分数" } },
                            "OPERAND2": 10
                          }
                        },
                        "SUBSTACK": [
                          {
                            "opcode": "control_wait",
                            "inputs": { "DURATION": 0.4 }
                          }
                        ]
                      }
                    },
                    {
                      "opcode": "control_wait",
                      "inputs": { "DURATION": 0.5 }
                    },
                    {
                      "opcode": "control_create_clone_of",
                      "inputs": { "CLONE_OPTION": "Enemy" }
                    }
                  ]
                }
              }
            ]
          }
        }
      ]
    },
    {
      "hat": "event_whenbroadcastreceived",
      "hatId": "hat_stage_spawn_apple_1",
      "hatFields": { "BROADCAST_OPTION": "生成苹果" },
      "blocks": [
        {
          "opcode": "control_forever",
          "inputs": {
            "SUBSTACK": [
              {
                "opcode": "control_if",
                "inputs": {
                  "CONDITION": {
                    "opcode": "operator_equals",
                    "inputs": {
                      "OPERAND1": { "opcode": "data_variable", "fields": { "VARIABLE": "状态" } },
                      "OPERAND2": "playing"
                    }
                  },
                  "SUBSTACK": [
                    {
                      "opcode": "control_wait",
                      "inputs": { "DURATION": 1 }
                    },
                    {
                      "opcode": "control_create_clone_of",
                      "inputs": { "CLONE_OPTION": "Apple" }
                    }
                  ]
                }
              }
            ]
          }
        }
      ]
    },
    {
      "hat": "event_whenflagclicked",
      "hatId": "hat_player_init_1",
      "blocks": [
        {
          "opcode": "looks_show"
        }
      ]
    },
    {
      "hat": "event_whenbroadcastreceived",
      "hatId": "hat_player_mouse_track_1",
      "hatFields": { "BROADCAST_OPTION": "游戏开始" },
      "blocks": [
        {
          "opcode": "control_forever",
          "inputs": {
            "SUBSTACK": [
              {
                "opcode": "control_if",
                "inputs": {
                  "CONDITION": {
                    "opcode": "operator_equals",
                    "inputs": {
                      "OPERAND1": { "opcode": "data_variable", "fields": { "VARIABLE": "状态" } },
                      "OPERAND2": "playing"
                    }
                  },
                  "SUBSTACK": [
                    {
                      "opcode": "motion_gotoxy",
                      "inputs": {
                        "X": { "opcode": "sensing_mousex" },
                        "Y": { "opcode": "sensing_mousey" }
                      }
                    }
                  ]
                }
              }
            ]
          }
        }
      ]
    },
    {
      "hat": "event_whenbroadcastreceived",
      "hatId": "hat_player_hide_1",
      "hatFields": { "BROADCAST_OPTION": "游戏结束" },
      "blocks": [
        {
          "opcode": "looks_hide"
        }
      ]
    },
    {
      "hat": "control_start_as_clone",
      "hatId": "hat_enemy_spawn_1",
      "blocks": [
        {
          "opcode": "motion_gotoxy",
          "inputs": {
            "X": { "opcode": "operator_random", "inputs": { "FROM": -220, "TO": 220 } },
            "Y": 170
          }
        },
        {
          "opcode": "control_forever",
          "inputs": {
            "SUBSTACK": [
              {
                "opcode": "motion_changeyby",
                "inputs": { "DY": -3 }
              },
              {
                "opcode": "control_if",
                "inputs": {
                  "CONDITION": {
                    "opcode": "sensing_touchingobject",
                    "inputs": { "TOUCHINGOBJECTMENU": "Player" }
                  },
                  "SUBSTACK": [
                    {
                      "opcode": "data_changevariableby",
                      "inputs": { "VALUE": -1 },
                      "fields": { "VARIABLE": "生命" }
                    },
                    {
                      "opcode": "control_delete_this_clone"
                    }
                  ]
                }
              },
              {
                "opcode": "control_if",
                "inputs": {
                  "CONDITION": {
                    "opcode": "sensing_touchingobject",
                    "inputs": { "TOUCHINGOBJECTMENU": "_edge_" }
                  },
                  "SUBSTACK": [
                    {
                      "opcode": "control_delete_this_clone"
                    }
                  ]
                }
              }
            ]
          }
        }
      ]
    },
    {
      "hat": "control_start_as_clone",
      "hatId": "hat_apple_spawn_1",
      "blocks": [
        {
          "opcode": "motion_gotoxy",
          "inputs": {
            "X": { "opcode": "operator_random", "inputs": { "FROM": -220, "TO": 220 } },
            "Y": 170
          }
        },
        {
          "opcode": "control_forever",
          "inputs": {
            "SUBSTACK": [
              {
                "opcode": "motion_changeyby",
                "inputs": { "DY": -2 }
              },
              {
                "opcode": "control_if",
                "inputs": {
                  "CONDITION": {
                    "opcode": "sensing_touchingobject",
                    "inputs": { "TOUCHINGOBJECTMENU": "Player" }
                  },
                  "SUBSTACK": [
                    {
                      "opcode": "data_changevariableby",
                      "inputs": { "VALUE": 1 },
                      "fields": { "VARIABLE": "分数" }
                    },
                    {
                      "opcode": "control_delete_this_clone"
                    }
                  ]
                }
              },
              {
                "opcode": "control_if",
                "inputs": {
                  "CONDITION": {
                    "opcode": "sensing_touchingobject",
                    "inputs": { "TOUCHINGOBJECTMENU": "_edge_" }
                  },
                  "SUBSTACK": [
                    {
                      "opcode": "control_delete_this_clone"
                    }
                  ]
                }
              }
            ]
          }
        }
      ]
    }
  ]
}
EOF
echo "DSL script written successfully"

